mapper.insert:
MERGE INTO SALES_DTL SD USING (SELECT #{virtualSalesNo} AS SALES_NO ,(COALESCE((SELECT MAX(SALES_SEQ) + 1 FROM SALES_DTL WHERE SALES_NO = #{virtualSalesNo} AND COMPANY_CODE = #{p.companyCode} AND DIVISION_CODE = #{p.divisionCode}), 1) + ROW_NUMBER() OVER (ORDER BY VSD.DELIVERY_CUSTOMER_CODE, VSD.CUSTOMER_ITEM_CODE) - 1) AS SALES_SEQ ,VSD.DIVISION_CODE AS DIVISION_CODE ,VSD.COMPANY_CODE AS COMPANY_CODE ,VSD.PRODUCT_CODE AS PRODUCT_CODE ,VSD.PRODUCT_NAME AS PRODUCT_NAME ,VSD.HS_CODE AS HS_CODE ,VSD.PRODUCT_UNIT AS PRODUCT_UNIT ,VSD.PRODUCT_ASSETS_TYPE AS PRODUCT_ASSETS_TYPE ,VSD.PROD_DIVISION_CODE AS PROD_DIVISION_CODE ,VSD.QUANTITY AS QUANTITY ,VSD.UNIT_PRICE AS UNIT_PRICE ,VSD.AMOUNT AS AMOUNT ,VSD.DELIVERY_CUSTOMER_CODE AS DELIVERY_CUSTOMER_CODE ,VSD.CUSTOMER_ITEM_CODE AS CUSTOMER_ITEM_CODE FROM (SELECT SD.DIVISION_CODE ,SD.COMPANY_CODE ,SD.PRODUCT_CODE ,SD.PRODUCT_NAME ,IM.HS_CODE ,SD.PRODUCT_UNIT ,SD.PRODUCT_ASSETS_TYPE ,SD.PROD_DIVISION_CODE ,SUM(SD.QUANTITY) AS QUANTITY ,COALESCE(MIN(SD.AMOUNT / NULLIF(SD.QUANTITY, 0)), 0) AS UNIT_PRICE ,SUM(SD.AMOUNT) AS AMOUNT ,SD.DELIVERY_CUSTOMER_CODE ,SD.CUSTOMER_ITEM_CODE FROM SALES_MST SM INNER JOIN SALES_DTL SD ON SM.SALES_NO = SD.SALES_NO AND SM.COMPANY_CODE = SD.COMPANY_CODE AND SM.DIVISION_CODE = SD.DIVISION_CODE INNER JOIN ITEM_MST IM ON IM.COMPANY_CODE = SD.COMPANY_CODE AND IM.ITEM_CODE = SD.PRODUCT_CODE WHERE SM.INVOICE_DATE LIKE #{p.yyyymm} || '%' AND SD.PRODUCT_CODE IN
#{productCode}
AND SM.COMPANY_CODE = #{p.companyCode} AND SM.DIVISION_CODE = #{p.divisionCode} AND SM.CUSTOMER_CODE = #{p.customerCode} AND SM.DELETE_YN = 'N' AND SM.VIRTUAL_YN = 'N' AND SM.EXPORT_FLAG = (SELECT SRC.EXPORT_FLAG FROM SALES_MST SRC WHERE SRC.SALES_NO = #{p.sourceSalesNo} AND SRC.COMPANY_CODE = #{p.companyCode} AND SRC.DIVISION_CODE = #{p.divisionCode}) GROUP BY SD.DIVISION_CODE, SD.COMPANY_CODE, SD.PRODUCT_CODE, SD.PRODUCT_NAME, SD.PRODUCT_UNIT, SD.PRODUCT_ASSETS_TYPE, IM.HS_CODE, SD.PROD_DIVISION_CODE, SD.DELIVERY_CUSTOMER_CODE, SD.CUSTOMER_ITEM_CODE) VSD WHERE VSD.QUANTITY > 0) VSD ON (SD.SALES_NO = VSD.SALES_NO AND SD.PRODUCT_CODE = VSD.PRODUCT_CODE AND SD.DIVISION_CODE = VSD.DIVISION_CODE AND SD.PROD_DIVISION_CODE = VSD.PROD_DIVISION_CODE AND SD.COMPANY_CODE = VSD.COMPANY_CODE AND SD.DELIVERY_CUSTOMER_CODE = VSD.DELIVERY_CUSTOMER_CODE) WHEN NOT MATCHED THEN INSERT (SALES_NO, SALES_SEQ, DIVISION_CODE, COMPANY_CODE, PRODUCT_CODE, PRODUCT_NAME, PRODUCT_UNIT, PRODUCT_ASSETS_TYPE, HS_CODE, PROD_DIVISION_CODE, QUANTITY, UNIT_PRICE, AMOUNT, BOM_STATUS, STATUS, DELIVERY_CUSTOMER_CODE, CREATE_DATE, CREATE_BY, UPDATE_DATE, UPDATE_BY, CUSTOMER_ITEM_CODE) VALUES (VSD.SALES_NO, VSD.SALES_SEQ, VSD.DIVISION_CODE, VSD.COMPANY_CODE, VSD.PRODUCT_CODE, VSD.PRODUCT_NAME, VSD.PRODUCT_UNIT, VSD.PRODUCT_ASSETS_TYPE, VSD.HS_CODE, VSD.PROD_DIVISION_CODE, VSD.QUANTITY, VSD.UNIT_PRICE, VSD.AMOUNT, '0', '1', VSD.DELIVERY_CUSTOMER_CODE, CURRENT_TIMESTAMP, 'fta', CURRENT_TIMESTAMP, 'fta', VSD.CUSTOMER_ITEM_CODE) WHEN MATCHED THEN UPDATE SET HS_CODE = VSD.HS_CODE ,QUANTITY = VSD.QUANTITY ,UNIT_PRICE = VSD.UNIT_PRICE ,AMOUNT = VSD.AMOUNT ,UPDATE_DATE = CURRENT_TIMESTAMP ,UPDATE_BY = 'fta'
